-- Generated from the seed catalogue definitions; edit the generator, not this file by hand.
-- Real products only. Every image key here has a source URL in image-sources.txt.

-- ---------- games ----------
INSERT INTO game (code, name, name_local, slug, logo_url, display_order, created_by, created_at)
SELECT v.code, v.name, v.name_local, v.slug, :'minio_base' || '/' || v.logo_key, v.display_order::smallint,
       pg_temp.uid('admin'), pg_temp.ago(400)
  FROM (VALUES
        ('POKEMON', 'Pokemon TCG', 'โปเกมอนการ์ดเกม', 'pokemon-tcg', 'seed/games/pokemon.png', 1),
        ('ONE_PIECE', 'One Piece Card Game', 'วันพีซการ์ดเกม', 'one-piece-card-game', 'seed/games/one-piece.webp', 2),
        ('MTG', 'Magic: The Gathering', 'เมจิก: เดอะ แกเธอริง', 'magic-the-gathering', 'seed/games/mtg.png', 3),
        ('YUGIOH', 'Yu-Gi-Oh! TCG', 'ยูกิโอ การ์ดเกม', 'yu-gi-oh-tcg', 'seed/games/yugioh.png', 4),
        ('DIGIMON', 'Digimon Card Game', 'ดิจิมอนการ์ดเกม', 'digimon-card-game', 'seed/games/digimon.png', 5),
        ('UNION_ARENA', 'Union Arena', 'ยูเนียนอารีน่า', 'union-arena', 'seed/games/union-arena.png', 6),
        ('DBS_FW', 'Dragon Ball Super Fusion World', 'ดราก้อนบอล ซูเปอร์ ฟิวชันเวิลด์', 'dragon-ball-fusion-world', 'seed/games/dbs-fw.png', 7)
       ) AS v(code, name, name_local, slug, logo_key, display_order);

