-- The four cross-game shelves come from a migration; this names them in Thai and gives every
-- shelf a picture, then adds the sub-shelves (one level deep, as the admin screen enforces).
UPDATE catalog_category SET name = 'การ์ดใบเดี่ยว', slug = 'single-cards', parent_id = NULL::int,
       display_order = 1, is_active = true, image_key = 'seed/products/charizard-ex-sir-199-165.png'
 WHERE code = 'SINGLES' AND game_id IS NOT DISTINCT FROM NULL::smallint;
INSERT INTO catalog_category (game_id, parent_id, code, name, slug, display_order, is_active, image_key)
