-- ---------- products ----------
INSERT INTO catalog_product (game_id, category_id, card_set_id, product_type, name, name_local, slug,
                             card_number, rarity_code, description, attributes, created_by, created_at, updated_at)
SELECT g.id, c.id, s.id, v.product_type, v.name, v.name_local, v.slug, v.card_number, v.rarity_code,
